-- RF Gestão SaaS: operações de domínio protegidas por sessão e tenant.
create or replace function public.app_tenant_usuario(p_token text) returns table(usuario_id uuid,empresa_id uuid,funcionario_id uuid,perfil text) language sql security definer set search_path=public,extensions as $$ select u.id,u.empresa_id,u.funcionario_id,u.perfil from public.sessoes s join public.usuarios u on u.id=s.usuario_id where s.token=p_token and s.expira_em>now() and u.ativo=true limit 1 $$;

create or replace function public.app_admin_prontuario(p_token text,p_funcionario_id uuid) returns jsonb language plpgsql security definer set search_path=public,extensions as $$ declare v record; v_func jsonb; begin select * into v from public.app_tenant_usuario(p_token) limit 1; if v.perfil not in('admin','administrador','gestor') then return jsonb_build_object('sucesso',false,'erro','Acesso negado'); end if; select to_jsonb(f) into v_func from public.funcionarios f where f.id=p_funcionario_id and f.empresa_id=v.empresa_id limit 1; if v_func is null then return jsonb_build_object('sucesso',false,'erro','Funcionário não encontrado'); end if; return jsonb_build_object('sucesso',true,'funcionario',v_func,'documentos',coalesce((select jsonb_agg(to_jsonb(d) order by d.created_at desc) from public.funcionario_documentos d where d.funcionario_id=p_funcionario_id and d.empresa_id=v.empresa_id),'[]'::jsonb),'advertencias',coalesce((select jsonb_agg(to_jsonb(a) order by a.data_ocorrencia desc) from public.funcionario_advertencias a where a.funcionario_id=p_funcionario_id and a.empresa_id=v.empresa_id),'[]'::jsonb),'timeline',coalesce((select jsonb_agg(to_jsonb(t) order by t.data_evento desc,t.created_at desc) from public.funcionario_timeline t where t.funcionario_id=p_funcionario_id and t.empresa_id=v.empresa_id),'[]'::jsonb),'atestados',coalesce((select jsonb_agg(to_jsonb(a) order by a.created_at desc) from public.atestados a where a.funcionario_id=p_funcionario_id),'[]'::jsonb),'justificativas',coalesce((select jsonb_agg(to_jsonb(j) order by j.data_registro desc) from public.justificativas_ponto j where j.funcionario_id=p_funcionario_id),'[]'::jsonb),'ponto',coalesce((select jsonb_agg(to_jsonb(r) order by r.data desc) from public.registros_ponto r where r.funcionario_id=p_funcionario_id limit 180),'[]'::jsonb),'holerites',coalesce((select jsonb_agg(to_jsonb(h) order by h.ano desc,h.mes desc) from public.holerites h where h.funcionario_id=p_funcionario_id and h.disponivel=true limit 6),'[]'::jsonb)); end; $$;

create or replace function public.app_admin_cadastrar_funcionario(p_token text,p_nome text,p_cpf text,p_data_nascimento date,p_tipo_vinculo text,p_cargo text,p_telefone text,p_endereco text,p_valor_mensal numeric,p_valor_diaria numeric,p_liberar_acesso boolean) returns jsonb language plpgsql security definer set search_path=public,extensions as $$ declare v record; v_id uuid; v_user uuid; v_reg boolean; begin select * into v from public.app_tenant_usuario(p_token) limit 1; if v.perfil not in('admin','administrador','gestor') then return jsonb_build_object('sucesso',false,'erro','Acesso negado'); end if; if trim(coalesce(p_nome,''))='' or length(regexp_replace(coalesce(p_cpf,''),'[^0-9]','','g'))<>11 then return jsonb_build_object('sucesso',false,'erro','Nome e CPF são obrigatórios'); end if; v_reg:=p_tipo_vinculo='formal'; insert into public.funcionarios(empresa_id,nome,cpf,data_nascimento,tipo_vinculo,registrado,cargo,telefone_celular,endereco,salario,valor_mensal,valor_diaria,elegivel_holerite,elegivel_escritorio,elegivel_vale,ativo,cadastro_tipo) values(v.empresa_id,trim(p_nome),regexp_replace(p_cpf,'[^0-9]','','g'),p_data_nascimento,p_tipo_vinculo, v_reg, nullif(trim(p_cargo),''),nullif(trim(p_telefone),''),nullif(trim(p_endereco),''),coalesce(p_valor_mensal,p_valor_diaria),p_valor_mensal,p_valor_diaria,v_reg,v_reg,true,true,case when v_reg then 'completo' else 'basico' end) returning id into v_id; if p_liberar_acesso then insert into public.usuarios(empresa_id,cpf,senha_hash,funcionario_id,primeiro_acesso,ativo,perfil,nome_exibicao) values(v.empresa_id,regexp_replace(p_cpf,'[^0-9]','','g'),crypt(to_char(p_data_nascimento,'DDMMYYYY'),gen_salt('bf')),v_id,true,true,'funcionario',trim(p_nome)) returning id into v_user; end if; insert into public.funcionario_timeline(empresa_id,funcionario_id,evento,descricao,origem,created_by) values(v.empresa_id,v_id,'Cadastro criado','Funcionário cadastrado no sistema','cadastro',v.usuario_id); return jsonb_build_object('sucesso',true,'funcionario_id',v_id,'usuario_id',v_user); exception when unique_violation then return jsonb_build_object('sucesso',false,'erro','CPF já cadastrado'); end; $$;

create or replace function public.app_admin_calcular_fechamento(p_token text,p_competencia text,p_incluir_informais_vale boolean default false) returns jsonb language plpgsql security definer set search_path=public,extensions as $$ declare v record; v_id uuid; v_inicio date; v_fim date; begin select * into v from public.app_tenant_usuario(p_token) limit 1; if v.perfil not in('admin','administrador','gestor') then return jsonb_build_object('sucesso',false,'erro','Acesso negado'); end if; if p_competencia !~ '^\d{4}-\d{2}$' then return jsonb_build_object('sucesso',false,'erro','Competência deve estar no formato AAAA-MM'); end if; v_inicio:=to_date(p_competencia||'-01','YYYY-MM-DD'); v_fim:=(v_inicio+interval '1 month-1 day')::date; insert into public.fechamentos_mensais(empresa_id,competencia,incluir_informais_vale,status,criado_por) values(v.empresa_id,p_competencia,p_incluir_informais_vale,'calculado',v.usuario_id) on conflict(empresa_id,competencia) do update set incluir_informais_vale=excluded.incluir_informais_vale,status='calculado' returning id into v_id; delete from public.fechamento_funcionarios where fechamento_id=v_id; insert into public.fechamento_funcionarios(fechamento_id,funcionario_id,dias_trabalhados,faltas,faltas_injustificadas,atrasos_minutos,horas_extras_50,horas_extras_100,dsr_horas,dsr_desconto,vale_elegivel,vale_valor,observacoes) select v_id,f.id,count(*) filter(where r.status is distinct from 'falta'),count(*) filter(where r.status='falta'),count(*) filter(where r.status='falta' and not exists(select 1 from public.atestados a where a.funcionario_id=f.id and a.status='aceito' and a.data_atendimento between r.data and r.data+interval '1 day')),0,0,0,0,0,(f.elegivel_vale and (p_incluir_informais_vale or f.registrado) and count(*) filter(where r.status='falta')=0),case when f.elegivel_vale and (p_incluir_informais_vale or f.registrado) and count(*) filter(where r.status='falta')=0 then coalesce((select vale_valor from public.configuracoes_empresa where empresa_id=v.empresa_id),300) else 0 end,null from public.funcionarios f left join public.registros_ponto r on r.funcionario_id=f.id and r.data between v_inicio and v_fim where f.empresa_id=v.empresa_id and f.ativo=true group by f.id; return jsonb_build_object('sucesso',true,'fechamento_id',v_id,'competencia',p_competencia); end; $$;

create or replace function public.app_admin_relatorio_fechamento(p_token text,p_competencia text,p_tipo text,p_incluir_informais_vale boolean default false) returns jsonb language plpgsql security definer set search_path=public,extensions as $$ declare v record; v_id uuid; v_rows jsonb; begin select * into v from public.app_tenant_usuario(p_token) limit 1; if v.perfil not in('admin','administrador','gestor') then return jsonb_build_object('sucesso',false,'erro','Acesso negado'); end if; select id into v_id from public.fechamentos_mensais where empresa_id=v.empresa_id and competencia=p_competencia limit 1; if v_id is null then return jsonb_build_object('sucesso',false,'erro','Calcule o fechamento antes de emitir o relatório'); end if; if p_tipo='escritorio' then select coalesce(jsonb_agg(to_jsonb(x) order by x.nome),'[]'::jsonb) into v_rows from (select f.nome,f.cpf,f.cargo,f.registrado,ff.dias_trabalhados,ff.faltas,ff.faltas_injustificadas,ff.atrasos_minutos,ff.horas_extras_50,ff.horas_extras_100,ff.dsr_horas,ff.dsr_desconto from public.fechamento_funcionarios ff join public.funcionarios f on f.id=ff.funcionario_id where ff.fechamento_id=v_id and f.elegivel_escritorio=true and f.registrado=true limit 1000)x; else select coalesce(jsonb_agg(to_jsonb(x) order by x.nome),'[]'::jsonb) into v_rows from (select f.nome,f.cpf,f.registrado,ff.faltas_injustificadas,ff.vale_elegivel,ff.vale_valor from public.fechamento_funcionarios ff join public.funcionarios f on f.id=ff.funcionario_id where ff.fechamento_id=v_id and ff.vale_elegivel and (p_incluir_informais_vale or f.registrado) limit 1000)x; end if; return jsonb_build_object('sucesso',true,'competencia',p_competencia,'tipo',p_tipo,'linhas',v_rows); end; $$;

create or replace function public.app_funcionario_beneficio(p_token text,p_competencia text) returns jsonb language plpgsql security definer set search_path=public,extensions as $$ declare v record; v_row jsonb; begin select * into v from public.app_tenant_usuario(p_token) limit 1; select to_jsonb(x) into v_row from (select f.nome,f.registrado,ff.faltas_injustificadas,ff.vale_elegivel,ff.vale_valor from public.fechamento_funcionarios ff join public.fechamentos_mensais fm on fm.id=ff.fechamento_id join public.funcionarios f on f.id=ff.funcionario_id where ff.funcionario_id=v.funcionario_id and fm.competencia=p_competencia limit 1)x; return jsonb_build_object('sucesso',true,'competencia',p_competencia,'beneficio',coalesce(v_row,'{}'::jsonb)); end; $$;

create or replace function public.app_admin_financeiro(p_token text) returns jsonb language plpgsql security definer set search_path=public,extensions as $$ declare v record; begin select * into v from public.app_tenant_usuario(p_token) limit 1; if v.perfil not in('admin','administrador','gestor') then return jsonb_build_object('sucesso',false,'erro','Acesso negado'); end if; return jsonb_build_object('sucesso',true,'contas',(select coalesce(jsonb_agg(to_jsonb(x) order by x.vencimento),'[]'::jsonb) from (select id,tipo,categoria,descricao,valor,vencimento,status,pago_em,observacoes from public.financeiro_lancamentos where empresa_id=v.empresa_id order by vencimento desc limit 500)x),'recorrencias',(select coalesce(jsonb_agg(to_jsonb(x) order by x.proximo_vencimento),'[]'::jsonb) from (select id,descricao,categoria,fornecedor,valor,periodicidade,proximo_vencimento,ativo from public.financeiro_recorrencias where empresa_id=v.empresa_id limit 300)x),'parcelas',(select coalesce(jsonb_agg(to_jsonb(x) order by x.vencimento),'[]'::jsonb) from (select p.id,p.numero,p.valor,p.vencimento,p.status,p.pago_em,p.comprovante_nome,s.credor,s.descricao from public.financeiro_parcelas p join public.financeiro_parcelamentos s on s.id=p.parcelamento_id where p.empresa_id=v.empresa_id limit 1000)x)); end; $$;

create or replace function public.app_admin_quitar_parcela(p_token text,p_id uuid,p_comprovante_url text default null,p_comprovante_nome text default null) returns jsonb language plpgsql security definer set search_path=public,extensions as $$ declare v record; begin select * into v from public.app_tenant_usuario(p_token) limit 1; if v.perfil not in('admin','administrador','gestor') then return jsonb_build_object('sucesso',false,'erro','Acesso negado'); end if; update public.financeiro_parcelas set status='pago',pago_em=current_date,comprovante_url=p_comprovante_url,comprovante_nome=p_comprovante_nome,baixado_por=v.usuario_id where id=p_id and empresa_id=v.empresa_id; return jsonb_build_object('sucesso',true); end; $$;

grant execute on all functions in schema public to anon,authenticated;
